node -e "
const fs = require('fs');
const https = require('http');

// Read and parse .env.test file
const envContent = fs.readFileSync('.env.test', 'utf8');
const envDict = {};

envContent.split('\n').forEach(line => {
  line = line.trim();
  if (line && !line.startsWith('#')) {
    const eqIndex = line.indexOf('=');
    if (eqIndex !== -1) {
      const key = line.substring(0, eqIndex).trim();
      const value = line.substring(eqIndex + 1).trim();
      envDict[key] = value;
    }
  }
});

console.log('Parsed env:', envDict);

// Create POST request
const data = JSON.stringify(envDict);
const options = {
  hostname: 'localhost',
  port: 47301,
  path: '/api/ci-secret-sync',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(data)
  }
};

const req = https.request(options, (res) => {
  console.log('Status Code:', res.statusCode);
  let responseData = '';
  res.on('data', (chunk) => {
    responseData += chunk;
  });
  res.on('end', () => {
    console.log('Response:', responseData);
  });
});

req.on('error', (e) => {
  console.error('Error making request:', e.message);
});

req.write(data);
req.end();
"

